{
	"name": "devil-ai",
	"version": "0.14.1",
	"description": "Devil AI — AI-powered coding assistant. Install everything with: npm install -g devil-ai",
	"license": "MIT",
	"type": "module",
	"main": "./dist/index.js",
	"types": "./dist/index.d.ts",
	"bin": {
		"devil-ai": "./bin/devil-ai"
	},
	"files": [
		"dist",
		"bin"
	],
	"scripts": {
		"build": "tsc",
		"dev": "tsc --watch",
		"check-types": "tsc --noEmit",
		"start": "node dist/cli.js",
		"postinstall": "echo '\\n  ⚡ Devil AI installed! Run \\x1b[1mdevil-ai setup\\x1b[0m to install dependencies.\\n'",
		"prepublishOnly": "npm run build"
	},
	"dependencies": {
		"commander": "^13.1.0",
		"chalk": "^5.4.1"
	},
	"devDependencies": {
		"@types/node": "^22.15.3",
		"typescript": "^5.8.3"
	},
	"engines": {
		"node": ">=18"
	},
	"keywords": [
		"ai",
		"coding-assistant",
		"opencode",
		"cli",
		"devil-ai",
		"setup"
	],
	"repository": {
		"type": "git",
		"url": "https://github.com/devilbhai/devil-ai"
	}
}
